import java.util.Iterator;
import java.util.List;
import java.util.Random;

/**
 * A simple model of a Hunter.
 * Hunters age, move, hunt lions, and die.
 * Hunters can bring other hunters after 898 steps to increse the hunter population.
 *
 * @version 2022.03.01
 */
public class Hunter extends Actor

{
    // Characteristics shared by all Hunters.
    private static final int MAX_AGE = 1000;
    private static final int SHOTS = 2; 
    /**
     * Create a Hunter. A hunter is created as an adult (age 50).
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Hunter(Field field, Location location)
    {
        super(field, location);
        setAge(50);
        setGrowthLevel(0);
    }

    /**
     * This is what the Hunter does most of the time: it hunts
     * lions during the night. In the process, it might die of old age.
     * 
     * @param newHunters A list to return new Hunters.
     * @param simulator The simulator.
     */
    public void act(List<Actor> newHunters,Simulator simulator){
        incrementAge(simulator.getSteps());
        if(!simulator.isDay()){
            if(isActive() ) {
                switch(simulator.getWeather()){
                    case RAINY:
                        hunt(0.7);
                        break;
                    case FOGGY:
                        hunt(0.4);
                        break;
                    default:
                        hunt(getRandom().nextDouble());
                        break;
                }
                Field field = getField();
                Location newLocation = field.freeAdjacentLocation(getLocation());
                if(newLocation != null) {
                    setLocation(newLocation);
                } 
                //hunter number increases as there are more hunters in the area who want to hunt.
                if (simulator.getSteps() % 898 ==  0){
                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
                    if(free.size() > 0) {
                        Location loc = free.remove(0);
                        Hunter hunter = new Hunter(field, loc);
                        newHunters.add(hunter);
                    }
                }
            }
        }
    }

    /**
     * This determine how the hunter hunts nearby lions
     * The hunter has 2 shots.
     * @param probability The probability the hunting is successful.
     */
    private void hunt(double probability){
        if(getRandom().nextDouble() < probability){
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            for(int i = 0; i< SHOTS; i++){
                Location where = it.next();
                Object animal = field.getObjectAt(where);
                if( animal != null && (animal instanceof Lion  || animal instanceof Cheetah)){
                    Animal currentAnimal = (Animal) animal;
                    if(currentAnimal.isActive()) { 
                        currentAnimal.setDead();
                        break;
                    }
                }
            }
        }
    }

    /**
     * Gets the max age of a hunter.
     * @return int. Max age of the hunter.
     */
    protected int getMaxAge(){
        return MAX_AGE;
    }
}

import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;

/**
 * Represent a rectangular grid of field positions.
 * Each position is able to store a single animal.
 *
 * @version 2016.02.29
 */
public class Field
{
    // A random number generator for providing random locations.
    private static final Random rand = Randomizer.getRandom();

    // The depth and width of the field.
    private int depth, width;
    // Storage for the animals.
    private Object[][] field;

    /**
     * Represent a field of the given dimensions.
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;
        field = new Object[depth][width];
    }

    /**
     * Empty the field.
     */
    public void clear()
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                field[row][col] = null;
            }
        }
    }

    /**
     * Clear the given location.
     * @param location The location to clear.
     */
    public void clear(Location location)
    {
        field[location.getRow()][location.getCol()] = null;
    }

    /**
     * Place an animal at the given location.
     * If there is already an animal at the location it will
     * be lost.
     * @param animal The animal to be placed.
     * @param row Row coordinate of the location.
     * @param col Column coordinate of the location.
     */
    public void place(Object animal, int row, int col)
    {
        place(animal, new Location(row, col));
    }

    /**
     * Place an animal at the given location.
     * If there is already an animal at the location it will
     * be lost.
     * @param animal The animal to be placed.
     * @param location Where to place the animal.
     */
    public void place(Object animal, Location location)
    {
        field[location.getRow()][location.getCol()] = animal;
    }

    /**
     * Return the animal at the given location, if any.
     * @param location Where in the field.
     * @return The animal at the given location, or null if there is none.
     */
    public Object getObjectAt(Location location)
    {
        return getObjectAt(location.getRow(), location.getCol());
    }

    /**
     * Return the animal at the given location, if any.
     * @param row The desired row.
     * @param col The desired column.
     * @return The animal at the given location, or null if there is none.
     */
    public Object getObjectAt(int row, int col)
    {
        return field[row][col];
    }

    /**
     * Generate a random location that is adjacent to the
     * given location, or is the same location.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location);
        return adjacent.get(0);
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);
        for(Location next : adjacent) {
            if(getObjectAt(next) == null) {
                free.add(next);
            }
        }
        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location freeAdjacentLocation(Location location)
    {
        // The available free ones.
        List<Location> free = getFreeAdjacentLocations(location);
        if(free.size() > 0) {
            return free.get(0);
        }
        else {
            return null;
        }
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> adjacentLocations(Location location)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -1; roffset <= 1; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -1; coffset <= 1; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return the depth of the field.
     * @return The depth of the field.
     */
    public int getDepth()
    {
        return depth;
    }

    /**
     * Return the width of the field.
     * @return The width of the field.
     */
    public int getWidth()
    {
        return width;
    }
}

import java.util.List;
import java.util.Random;

/**
 * An actor is a representation of a living thing in the simulation.
 *
 * @version 2022.03.01
 */
public abstract class Actor 
{
    // The actor's field.
    private Field field;
    // The actor's position in the field.
    private Location location;
    // Whether the actor is alive or not.
    private boolean alive;
    //The actor's age
    private int age;
    //how much the actor grows. This is added to the animals food level.
    private double growthLevel;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();
    /**
     * Create a new actor at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Actor(Field field, Location location)
    {
        this.field = field;
        setLocation(location);
        alive = true;
    }

    /**
     * Return the actor's location.
     * @return The actors's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the actor at the new location in the given field.
     * @param newLocation The actor's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Return the actors's field.
     * @return The actors's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Set the field.
     * @param place. The field.
     */
    protected void setField(Field place){
        field = place;
    }

    /**
     * Check whether the actor is alive or not.
     * @return true if the actor is still alive.
     */
    protected boolean isActive()
    {
        return alive;
    }

    /**
     * Set if the actor is alive or not.
     * @param alive. If the actor is alive.
     */
    protected void setAlive(boolean alive)
    {
        this.alive = alive;
    }

    /**
     * Indicate that the actor is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        setAlive(false);
        if(getLocation() != null) {
            getField().clear(getLocation());
            location = null ;
            field = null;
        }
    }

    /**
     * Make this actor act - that is: make it do
     * whatever it wants/needs to do.
     * @param newActors A list to receive newly born actors.
     * @param simulator The simulator.
     */
    public abstract void act(List<Actor> newActors, Simulator simulator);

    /**
     * Get age of an actor
     * @return age of the actor.
     */
    protected int getAge(){
        return age;
    }

    /**
     * Set age of an actor
     * @param age. Age of the actor.
     */
    protected void setAge(int  age){
        this.age = age ;
    }

    /**
     * Increase the age. This could result in the actor's death.
     * Actor's age only increases once every 4 steps.
     * @param step. The number of steps in the simulation
     */
    protected void incrementAge(int step)
    {
        if(step % 4 == 0){
            age++;
        }
        if(age > getMaxAge()) {
            setDead();
        }
    }

    /**
     * Gets the max age of an actor.
     * @return Max age of the actor.
     */
    abstract protected int getMaxAge();

    /**
     * Return how much the actor has grown.
     * @return  How much the actor grows.
     */
    protected double getGrowthLevel(){
        return growthLevel;
    }

    /**
     * Increase the actor growth level by how much the actor has grown during this step.
     * @param value. How much more the actor has grown.
     */
    protected void setGrowthLevel(double value){
        growthLevel = value + growthLevel;
    }

    /**
     * Returns the shared random generator object
     * @return The random generator object
     */
    protected Random getRandom(){
        return rand;
    }
}

